use super::super::fir::{WindowType, generate_window};
use super::fir_design_config::FirDesignConfig;
use super::fir_phase::FirPhase;
use super::fir_phase::finalize_impulse_response;
use super::misc::compute_minimum_phase_from_magnitude;
use super::misc::interpolate_log_space;
use super::misc::spectrum_to_impulse_response;
